<script setup lang="ts">
import {computed,ref} from 'vue'; import {useRouter} from 'vue-router'; import {useQuery} from '@tanstack/vue-query'; import {productRepository} from '../../services/productRepository'; import DetailDrawer from '../../components/common/DetailDrawer.vue'; import DetailFields from '../../components/common/DetailFields.vue'; import ListPagination from '../../components/common/ListPagination.vue'; import StatusTag from '../../components/common/StatusTag.vue'; import VersionForm from '../../components/product/VersionForm.vue'; import RequirementForm from '../../components/product/RequirementForm.vue'; import {requirementRepository} from '../../services/requirementRepository'; import RequirementActivity from '../../components/product/RequirementActivity.vue'; import RequirementWorkItems from '../../components/product/RequirementWorkItems.vue'; import RequirementActions from '../../components/product/RequirementActions.vue';
const props=defineProps<{kind:'versions'|'requirements'}>(); const router=useRouter(); const config={versions:{title:'版本迭代',kicker:'VERSION ITERATIONS',query:productRepository.versions,columns:['迭代名称','产品线','状态','负责人','完成度'],keys:['name','productLineName','status','ownerName','progress'],fields:[{key:'name',label:'迭代名称'},{key:'productLineName',label:'产品线'},{key:'status',label:'状态'},{key:'ownerName',label:'负责人'},{key:'startDate',label:'开始日期'},{key:'endDate',label:'结束日期'},{key:'progress',label:'完成度'}]},requirements:{title:'需求任务',kicker:'REQUIREMENT TASKS',query:productRepository.requirements,columns:['需求标题','状态','负责人','优先级','创建时间'],keys:['title','status','ownerName','priority','createdAt'],fields:[{key:'title',label:'需求标题'},{key:'code',label:'需求编号'},{key:'status',label:'状态'},{key:'ownerName',label:'负责人'},{key:'priority',label:'优先级'},{key:'productLineName',label:'产品线'},{key:'versionName',label:'迭代版本'},{key:'description',label:'需求描述'}]}} as const; const current=computed(()=>config[props.kind]); const keyword=ref(''); const selected=ref<Record<string,unknown>|null>(null); const page=ref(1); const editorOpen=ref(false); const editing=ref<Record<string,unknown>|null>(null); const saving=ref(false); const saveError=ref(''); const pageSize=10; const query=useQuery({queryKey:computed(()=>['product',props.kind]),queryFn:()=>current.value.query({page:1,pageSize:100})}); const refresh=()=>{void query.refetch()}; const openWorkItem=(item:Record<string,unknown>)=>{const type=String(item.taskType||''); const view=type==='bug'?'prod_bugs':type==='design'?'prod_design_tasks':'prod_rd_tasks'; router.push({path:`/app/${view}`,query:{workItemId:String(item.id||'')}});}; const rows=computed(()=>{const items=query.data.value?.items||[]; const key=keyword.value.trim().toLowerCase(); return key?items.filter(item=>Object.values(item).some(value=>String(value??'').toLowerCase().includes(key))):items}); const pagedRows=computed(()=>rows.value.slice((page.value-1)*pageSize,page.value*pageSize)); const cell=(row:Record<string,unknown>,index:number)=>row[current.value.keys[index]]??'—'; const openCreate=()=>{editing.value=null;saveError.value='';editorOpen.value=true}; const saveRequirement=async(value:Record<string,unknown>)=>{if(props.kind!=='requirements')return;if(!String(value.title||'').trim()||!String(value.productLineId||'').trim()){saveError.value='请填写需求标题并选择产品线';return;}saving.value=true;saveError.value='';try{if(editing.value?.id)await requirementRepository.update(String(editing.value.id),value);else await requirementRepository.create(value);editorOpen.value=false;selected.value=null;await query.refetch()}catch(error){saveError.value=error instanceof Error?error.message:'保存失败'}finally{saving.value=false}}; const openEdit=()=>{if(selected.value){editing.value=selected.value;saveError.value='';editorOpen.value=true}}; const saveVersion=async(value:Record<string,unknown>)=>{if(!String(value.name||'').trim()||!String(value.productLineId||'').trim()){saveError.value='请填写版本名称并选择产品线';return;} saving.value=true;saveError.value='';try{const lineId=String(value.productLineId);if(editing.value?.id)await productRepository.updateVersion(lineId,String(editing.value.id),value);else await productRepository.createVersion(lineId,value);editorOpen.value=false;selected.value=null;await query.refetch()}catch(error){saveError.value=error instanceof Error?error.message:'保存失败'}finally{saving.value=false}};
</script>
<template><section class="crm-view"><div class="section-heading"><div><span class="eyebrow">{{current.kicker}}</span><h2>{{current.title}}</h2></div><button class="primary" @click="openCreate">{{kind==='versions' ? '新建版本' : '新建需求'}}</button><button class="secondary" @click="refresh">刷新</button></div><div class="toolbar"><input v-model="keyword" :placeholder="`搜索${current.title}`"/><span>{{rows.length}} 条记录</span></div><div v-if="query.isPending" class="state">正在加载{{current.title}}…</div><div v-else-if="query.isError" class="state error">{{current.title}}加载失败。</div><div v-else-if="!rows.length" class="state">暂无匹配记录。</div><template v-else><div class="table-wrap"><table><thead><tr><th v-for="column in current.columns" :key="column">{{column}}</th></tr></thead><tbody><tr v-for="row in pagedRows" :key="String(row.id)" @click="selected=row"><td v-for="(_,index) in current.columns" :key="index"><StatusTag v-if="current.keys[index]==='status'||current.keys[index]==='priority'" :status="cell(row,index)"/><template v-else>{{cell(row,index)}}</template></td></tr></tbody></table></div><ListPagination :page="page" :page-size="pageSize" :total="rows.length" @change="page=$event"/></template><DetailDrawer :open="Boolean(selected)" :title="`${current.title}详情`" @close="selected=null"><DetailFields v-if="selected" :record="selected" :fields="[...current.fields]"/><RequirementActions v-if="kind==='requirements' && selected?.id" :requirement-id="String(selected.id)" :status="String(selected.status||'')" @changed="query.refetch(); selected=null"/><RequirementActivity v-if="kind==='requirements' && selected?.id" :requirement-id="String(selected.id)"/><RequirementWorkItems v-if="kind==='requirements' && selected?.id" :requirement-id="String(selected.id)" @open="openWorkItem"/><div v-if="kind==='versions'" class="form-actions"><button class="secondary" @click="openEdit">编辑</button></div></DetailDrawer><DetailDrawer :open="editorOpen" :title="editing ? `编辑${current.title}` : `新建${current.title}`" @close="editorOpen=false"><VersionForm v-if="kind==='versions'" :model-value="editing" @save="saveVersion" @cancel="editorOpen=false"/><RequirementForm v-else :model-value="editing" @save="saveRequirement" @cancel="editorOpen=false"/></DetailDrawer></section></template>
